package kz.zani.mobile

import androidx.lifecycle.viewModelScope
import kotlinx.coroutines.*
import kotlinx.coroutines.test.*
import kz.zani.mobile.core.*
import kz.zani.mobile.data.*
import kz.zani.mobile.ui.*
import org.json.JSONObject
import org.junit.Assert.*
import org.junit.Test

@OptIn(ExperimentalCoroutinesApi::class)
class TaskAppointmentEditTest {
    private fun fixture(name:String)=javaClass.classLoader!!.getResourceAsStream("fixtures/$name.json")!!.bufferedReader().use {it.readText()}
    private fun catalog()=JSONObject(fixture("task-appointment-partial-cases"))
    private fun detail(b:Int=101,id:Int=1101)=JsonContracts.taskDetails(fixture("task-$b-$id"))
    private val context=TaskCommentContext(101,1101,1)
    private fun source(revision:Int=1,epoch:Int=1,original:TaskAppointmentOriginal=detail().appointmentRead)=TaskAppointmentEditSource(TaskCommentRead(TaskCommentContext(101,1101,epoch),revision),detail().task,original)
    private fun choice()=TaskDraftAppointmentChoice.make(JsonContracts.detail(fixture("appointment-101-501")),101,501)!!
    private fun draft(mode:TaskAppointmentEditMode)=TaskAppointmentEditDraft(mode,choice(),source().read,"2026-10-28")
    private class Port(update:Boolean=true):SyntheticTaskAppointmentEditPort {
        override val grants=listOf(SyntheticTaskAppointmentEditGrant(101,1101,9001,update),SyntheticTaskAppointmentEditGrant(202,1201,9002,update));val calls=mutableListOf<TaskAppointmentEditAttempt>();val pending=mutableListOf<CompletableDeferred<SyntheticTaskAppointmentEditOutcome>>()
        override suspend fun execute(attempt:TaskAppointmentEditAttempt):SyntheticTaskAppointmentEditOutcome {calls+=attempt;return CompletableDeferred<SyntheticTaskAppointmentEditOutcome>().also {pending+=it}.await()}
    }
    private class Reads:AgendaRepository {
        val lists=mutableListOf<CompletableDeferred<AppointmentList>>();val details=mutableListOf<CompletableDeferred<AppointmentDetail>>()
        override suspend fun bootstrap():Bootstrap=error("No bootstrap in Task relation picker")
        override suspend fun appointments(business:Int,day:String)=CompletableDeferred<AppointmentList>().also {lists+=it}.await()
        override suspend fun appointment(business:Int,id:Int)=CompletableDeferred<AppointmentDetail>().also {details+=it}.await()
    }
    private inner class Repo:TaskReadRepository,AgendaRepository {
        override suspend fun tasks(business:Int)=JsonContracts.tasks(fixture("tasks-$business"))
        override suspend fun taskDetails(business:Int,id:Int)=detail(business,id)
        override suspend fun bootstrap():Bootstrap=error("No bootstrap")
        override suspend fun appointments(business:Int,day:String)=JsonContracts.appointments(fixture("appointments-$business"))
        override suspend fun appointment(business:Int,id:Int)=JsonContracts.detail(fixture("appointment-$business-$id"))
    }
    private fun check(block:suspend TestScope.(TaskAppointmentEditModel,Port,Reads)->Unit)=runTest {val p=Port();val r=Reads();val m=TaskAppointmentEditModel(p,this,r);m.bind(source());try {block(m,p,r)}finally {m.bind(null)}}
    private fun TestScope.list(m:TaskAppointmentEditModel,r:Reads) {m.open(m.control);m.choose(TaskAppointmentEditMode.SET,m.control);m.updateDay("2026-10-28",m.inputControl);m.readAppointments(m.control,m.picker.control);runCurrent();r.lists.last().complete(JsonContracts.appointments(fixture("appointments-101")));runCurrent()}
    private fun TestScope.select(m:TaskAppointmentEditModel,r:Reads) {list(m,r);m.openAppointment(501,m.control,m.picker.control);runCurrent();r.details.last().complete(JsonContracts.detail(fixture("appointment-101-501")));runCurrent();m.useAppointment(m.control,m.picker.control)}
    @Test fun strictOriginalProjectionUsesExactExistingGetFieldAndKeepsUnknownDistinctFromNull() {val rows=catalog().getJSONArray("original_cases");for(i in 0 until rows.length()){val row=rows.getJSONObject(i);val expected=when(row.getString("kind")){"appointment"->TaskAppointmentOriginal.Appointment(row.getInt("id"));"notSet"->TaskAppointmentOriginal.NotSet;else->TaskAppointmentOriginal.Unknown};assertEquals(row.getString("name"),expected,TaskAppointmentOriginal.decode(row.getString("payload_json")));val parsed=runCatching {JsonContracts.taskDetails(row.getString("payload_json"))}.getOrNull();if(parsed!=null)assertEquals(expected,parsed.appointmentRead)}}
    @Test fun oneFieldSetNullAndSeparateUpdateGrantDoNotSerializeAnyOtherTaskField() {val s=source();assertNull(TaskAppointmentEditDraft().change(s));val auth=SyntheticTaskAppointmentEditGrant(101,1101,9001,true).authorization(context)!!;assertNull(SyntheticTaskAppointmentEditGrant(101,1101,9001,false).authorization(context));for(mode in TaskAppointmentEditMode.entries){val review=TaskAppointmentEditReview(s,1,draft(mode));val a=TaskAppointmentEditLedger().begin(review,auth)!!;val body=JSONObject(a.preparedBody()!!);assertEquals(setOf("appointment"),body.keys().asSequence().toSet());if(mode==TaskAppointmentEditMode.CLEAR)assertTrue(body.isNull("appointment"))else assertEquals(501,body.getInt("appointment"));assertEquals(review.draft,a.review.draft)}}
    @Test fun unknownOriginalOldReadForeignChoiceAndUnchosenDayCannotCreateReview() {val d=draft(TaskAppointmentEditMode.SET);assertNull(d.copy(day="").change(source()));assertNull(d.copy(choiceRead=TaskCommentRead(context,2)).change(source()));assertNull(d.copy(choice=TaskDraftAppointmentChoice.make(JsonContracts.detail(fixture("appointment-202-601")),202,601)).change(source()));assertNull(d.change(source(original=TaskAppointmentOriginal.Unknown)));assertNull(draft(TaskAppointmentEditMode.CLEAR).change(source(original=TaskAppointmentOriginal.Unknown)));for(status in listOf("open","in_progress","done","cancelled","future-status")){val s=source().copy(task=detail().task.copy(status=status));assertEquals(status in setOf("open","in_progress"),s.valid)}}
    @Test fun sharedSelectedGenericFkAndExactTaskBusinessStatusTimestampOutcomeMustMatch() {val rows=catalog().getJSONArray("result_cases");val auth=SyntheticTaskAppointmentEditGrant(101,1101,9001,true).authorization(context)!!;for(i in 0 until rows.length()){val row=rows.getJSONObject(i);val mode=if(row.getString("mode")=="clear")TaskAppointmentEditMode.CLEAR else TaskAppointmentEditMode.SET;val r=TaskAppointmentEditReview(source(),1,draft(mode));val ledger=TaskAppointmentEditLedger();val a=ledger.begin(r,auth)!!;val body=a.preparedBody();assertNull(ledger.begin(r,auth));assertFalse(ledger.acknowledge(auth));ledger.complete(a,SyntheticTaskAppointmentEditOutcome.Response(row.getInt("status"),row.getString("response_json")));val record=ledger.visible(auth)!!;assertEquals(row.getString("name"),row.getBoolean("accepted"),record.phase==TaskAppointmentEditPhase.CONFIRMED);assertEquals(body,record.attempt.preparedBody());assertEquals(r,record.attempt.review);if(!row.getBoolean("accepted")){assertFalse(ledger.acknowledge(auth));assertTrue(ledger.blocked(TaskCommentContext(101,1101,2)));assertNull(ledger.visible(SyntheticTaskAppointmentEditGrant(101,1101,9001,true).authorization(TaskCommentContext(101,1101,2))));assertNull(ledger.begin(r,auth))}}}
    @Test fun openingHasNoModeCandidateDateOrAutomaticGetAndOldModeInputCannotOverwrite()=check {m,_,r->assertTrue(m.canOpen);m.open(m.control);m.prepare(m.control);assertNull(m.review);assertTrue(m.showsIssue);assertNull(m.draft.mode);assertTrue(m.draft.day.isEmpty());assertTrue(r.lists.isEmpty());m.choose(TaskAppointmentEditMode.SET,m.control);val input=m.inputControl;val child=m.picker.control;m.updateDay("2026-10-28",input);m.choose(TaskAppointmentEditMode.CLEAR,m.control);val saved=m.draft;m.updateDay("overwrite",input);assertEquals(saved,m.draft)}
    @Test fun closeQuarantinesLateListAndReopenRetainsOnlyExplicitRawDay()=check {m,_,r->m.open(m.control);m.choose(TaskAppointmentEditMode.SET,m.control);m.updateDay("2026-10-28",m.inputControl);m.readAppointments(m.control,m.picker.control);runCurrent();val saved=m.draft;m.back(m.control);val closed=m.control;r.lists.last().complete(JsonContracts.appointments(fixture("appointments-101")));runCurrent();assertEquals(closed,m.control);assertEquals(saved,m.draft);assertNull(m.picker.state.context);m.open(m.control);assertEquals("2026-10-28",m.picker.state.day);assertFalse(m.picker.state.loaded)}
    @Test fun currentWindowAndCompletedIndependentDetailRequiredBeforeSelection()=check {m,_,r->list(m,r);m.openAppointment(999999,m.control,m.picker.control);assertNull(m.picker.state.selectedID);m.openAppointment(501,m.control,m.picker.control);runCurrent();val pending=m.picker.control;m.useAppointment(m.control,pending);assertNull(m.draft.choice);r.details.last().complete(JsonContracts.detail(fixture("appointment-101-501")));runCurrent();m.useAppointment(m.control,pending);assertNull(m.draft.choice);m.useAppointment(m.control,m.picker.control);assertEquals(501,m.draft.choice!!.id);assertEquals(source().read,m.draft.choiceRead)}
    @Test fun foreignThenExplicitRetryDoesNotDefaultOrMutateOriginalTask()=check {m,_,r->val original=m.source;list(m,r);m.openAppointment(501,m.control,m.picker.control);runCurrent();r.details.last().complete(JsonContracts.detail(fixture("appointment-202-601")));runCurrent();assertEquals(ReadProblem.INVALID_PAYLOAD,m.picker.state.problem);assertNull(m.draft.choice);m.retryAppointment(m.control,m.picker.control);runCurrent();r.details.last().complete(JsonContracts.detail(fixture("appointment-101-501")));runCurrent();m.useAppointment(m.control,m.picker.control);assertEquals(original,m.source)}
    @Test fun reviewBackModeSwitchAndLocalResetKeepCandidateDayAndDoNotClearServerRelation()=check {m,_,r->select(m,r);val selected=m.draft;m.prepare(m.control);m.back(m.control);assertEquals(selected,m.draft);m.choose(TaskAppointmentEditMode.CLEAR,m.control);m.prepare(m.control);assertTrue(JSONObject(m.review!!.change!!.body()!!).isNull("appointment"));m.back(m.control);m.choose(TaskAppointmentEditMode.SET,m.control);assertEquals(selected,m.draft);m.askClear(m.control);val old=m.clearConfirmation!!;m.dismissClear(old);m.choose(TaskAppointmentEditMode.CLEAR,m.control);m.confirmClear(old);assertEquals(TaskAppointmentEditMode.CLEAR,m.draft.mode);m.askClear(m.control);m.confirmClear(m.clearConfirmation!!);assertEquals(TaskAppointmentEditDraft(),m.draft);assertEquals(source(),m.source)}
    @Test fun changedTaskReadRequiresReselectWhileRawCandidateRemainsUnsentInput()=check {m,_,r->select(m,r);val selected=m.draft;m.bind(source(revision=2));m.open(m.control);m.prepare(m.control);assertNull(m.review);assertEquals(selected,m.draft);assertEquals(selected.day,m.picker.state.day);assertFalse(m.picker.state.loaded);assertTrue(m.showsIssue)}
    @Test fun unknownKeepsOriginalModeCandidateDayBodyAttemptAndCannotRekeyOnMatchingReread()=check {m,p,r->select(m,r);m.prepare(m.control);val review=m.review!!;val control=m.control;m.launchSubmit(control);runCurrent();val a=p.calls.single();val body=a.preparedBody();m.choose(TaskAppointmentEditMode.CLEAR,m.control);m.askClear(m.control);m.launchSubmit(m.control);runCurrent();assertEquals(1,p.calls.size);assertEquals(review.draft,m.draft);p.pending.single().completeExceptionally(ReadException(ReadProblem.UNAVAILABLE));runCurrent();assertEquals(TaskAppointmentEditPhase.UNKNOWN,m.submission!!.phase);m.bind(source(revision=2,original=TaskAppointmentOriginal.Appointment(501)));assertTrue(m.blocked);assertEquals(body,m.submission!!.attempt.preparedBody());assertEquals(review,m.submission!!.attempt.review);m.bind(source(revision=3,epoch=2));assertTrue(m.blocked);assertNull(m.submission);assertFalse(m.canOpen);assertEquals(1,m.retainedAttemptCount)}
    @Test fun unknownTaskDoesNotBlockIndependentBusinessAndUnknownOriginalDoesNotGrantNullEdit()=check {m,p,_->m.open(m.control);m.choose(TaskAppointmentEditMode.CLEAR,m.control);m.prepare(m.control);m.launchSubmit(m.control);runCurrent();p.pending.single().complete(SyntheticTaskAppointmentEditOutcome.Unknown);runCurrent();val other=detail(202,1201);m.bind(TaskAppointmentEditSource(TaskCommentRead(TaskCommentContext(202,1201,2),2),other.task,other.appointmentRead));assertTrue(m.canOpen);assertFalse(m.blocked);m.bind(source(revision=2,original=TaskAppointmentOriginal.Unknown));assertFalse(m.canOpen)}
    @Test fun fakeClearConfirmsSeparatelyConsumesOnlyThisReadAndNeverOptimisticallyChangesGet()=runTest {val original=source();val m=TaskAppointmentEditModel(FixtureTaskAppointmentEditPort(fixture("task-appointment-partial-outcome")),this,Repo());m.bind(original);m.open(m.control);m.choose(TaskAppointmentEditMode.CLEAR,m.control);m.prepare(m.control);m.submit(m.control);val record=m.submission!!;assertEquals(TaskAppointmentEditPhase.CONFIRMED,record.phase);assertNull(record.result!!.value);assertEquals(original,m.source);m.acknowledge(m.control,record);assertTrue(m.consumed);assertFalse(m.canOpen);assertEquals(original,m.source);m.bind(null)}
    @Test fun defaultOwnerAndGetOnlyOrMissingIndependentReadPortCannotCreateUpdateEditor()=runTest {Dispatchers.setMain(StandardTestDispatcher(testScheduler));val repo=Repo();val origin=object:TaskCommentDraftSource {override suspend fun matchesFixture(detail:TaskDetails)=detail==this@TaskAppointmentEditTest.detail()};val plain=TaskListViewModel(repo,commentSource=origin);val noRead=TaskListViewModel(repo,commentSource=origin,appointmentEditSubmission=Port());try {plain.load(101,1);noRead.load(101,1);runCurrent();plain.open(1101);noRead.open(1101);runCurrent();assertNull(plain.appointmentEdit);assertNull(noRead.appointmentEdit);val noGrant=TaskAppointmentEditModel(Port(false),this,repo);noGrant.bind(source());assertFalse(noGrant.canPresent)}finally {plain.viewModelScope.cancel();noRead.viewModelScope.cancel();Dispatchers.resetMain()}}
    @Test fun taskListLaneAndRawCommentCannotBypassUnknownRelationWriteAcrossEpoch()=runTest {Dispatchers.setMain(StandardTestDispatcher(testScheduler));val repo=Repo();val p=Port();val origin=object:TaskCommentDraftSource {override suspend fun matchesFixture(detail:TaskDetails)=detail==this@TaskAppointmentEditTest.detail()};val m=TaskListViewModel(repo,commentSource=origin,dateEditSubmission=FixtureTaskDateEditPort(fixture("task-date-partial-outcome")),titleEditSubmission=FixtureTaskTitleEditPort(fixture("task-title-partial-outcome")),appointmentEditSubmission=p,appointmentEditReads=repo);try {m.load(101,1);runCurrent();m.open(1101);runCurrent();val a=m.appointmentEdit!!;val parent=m.control;m.openAppointmentEdit(a.control,parent);m.openDateEdit(m.dateEdit!!.control,parent);assertTrue(a.editing);assertFalse(m.dateEdit.editing);assertFalse(m.dateEditCurrent(parent));a.choose(TaskAppointmentEditMode.CLEAR,a.control);a.prepare(a.control);a.launchSubmit(a.control);runCurrent();p.pending.single().completeExceptionally(ReadException(ReadProblem.UNAVAILABLE));runCurrent();val state=m.state;assertTrue(m.taskActionOccupied);assertFalse(m.titleEditCurrent(m.control));m.comment?.state?.read?.let {m.openComment(it)};assertNull(m.comment?.state?.selection);assertEquals(state,m.state);m.load(101,2);runCurrent();m.open(1101);runCurrent();assertTrue(m.taskActionOccupied);assertFalse(m.hasHiddenRetainedAction);assertTrue(a.canPresent);assertTrue(a.blocked);assertTrue(m.appointmentEditCurrent(m.control));assertFalse(m.dateEditCurrent(m.control));assertFalse(m.titleEditCurrent(m.control));assertNull(a.submission);assertEquals(1,a.retainedAttemptCount)}finally {m.viewModelScope.cancel();Dispatchers.resetMain()}}
    @Test fun lateSourceBusinessChangeRejectsOldChoiceAndInputCallbacks()=check {m,_,r->list(m,r);m.openAppointment(501,m.control,m.picker.control);runCurrent();val control=m.control;val child=m.picker.control;val input=m.inputControl;val other=detail(202,1201);m.bind(TaskAppointmentEditSource(TaskCommentRead(TaskCommentContext(202,1201,2),2),other.task,other.appointmentRead));r.details.last().complete(JsonContracts.detail(fixture("appointment-101-501")));runCurrent();m.useAppointment(control,child);m.updateDay("2026-10-28",input);assertNull(m.draft.choice);assertTrue(m.draft.day.isEmpty());assertEquals(202,m.source!!.read.context.business)}
    @Test fun parentDateInputSurvivesConsecutiveEventsButNotReadModeOrTaskSource()=check {m,_,r->
        m.open(m.control);m.choose(TaskAppointmentEditMode.SET,m.control);val input=m.inputControl!!;val read=m.picker.control
        for(raw in listOf("2","20","2026-10-28")){m.updateDay(raw,input);assertEquals(raw,m.draft.day);assertEquals(input,m.inputControl)}
        m.readAppointments(m.control,read);runCurrent();assertTrue(r.lists.isEmpty());m.readAppointments(m.control,m.picker.control);runCurrent();m.updateDay("overwrite",input);assertNull(m.inputControl);assertEquals("2026-10-28",m.draft.day)
        r.lists.single().complete(JsonContracts.appointments(fixture("appointments-101")));runCurrent();m.updateDay("overwrite",input);assertEquals("2026-10-28",m.draft.day);assertNotEquals(input,m.inputControl)
        val mode=m.inputControl!!;m.choose(TaskAppointmentEditMode.CLEAR,m.control);m.choose(TaskAppointmentEditMode.SET,m.control);m.updateDay("overwrite",mode);assertEquals("2026-10-28",m.draft.day);assertNotEquals(mode,m.inputControl)
        val source=m.inputControl!!;val old=m.source!!;m.bind(old.copy(read=old.read.copy(revision=2)));m.open(m.control);m.choose(TaskAppointmentEditMode.SET,m.control);m.updateDay("overwrite",source);assertEquals("2026-10-28",m.draft.day);assertNull(m.draft.choiceRead);assertNotEquals(source,m.inputControl)
    }
}
